"""`mac connector` — generated by tools/gen_groups.py from local-mac's connector__* handlers. Do not edit."""
from mac.cli import json_object
from mac.groups._backend import call


def register(registry):
    @registry.verb("connector", "health", mode="read",
                   desc='health-check the local OpenConnector container (GET /v1/health)')
    def connector_health(ns):
        return call('connector', 'health')

    def connector_list_actions_args(p):
        p.add_argument('--service', default='')

    @registry.verb("connector", "list_actions", mode="read",
                   desc="list available OpenConnector Actions, optionally filtered by provider service (e.g. 'gmail')", args=connector_list_actions_args)
    def connector_list_actions(ns):
        return call('connector', 'list_actions', service=ns.service)

    def connector_execute_action_args(p):
        p.add_argument('action_id')
        p.add_argument('--input', default=None, type=json_object)
        p.add_argument('--idempotency-key', default='')
        p.add_argument('--alias', default='')

    @registry.verb("connector", "execute_action", mode="write",
                   desc="execute one OpenConnector Action by id (e.g. 'gmail.search_threads') with a JSON input payload", args=connector_execute_action_args)
    def connector_execute_action(ns):
        return call('connector', 'execute_action', action_id=ns.action_id, input=ns.input, idempotency_key=ns.idempotency_key, alias=ns.alias)
